import pandas as pd, numpy as np
from lmfit import Model, Parameters
d=pd.read_csv('spectrum.csv')
x=d.shift_cm1.values; y=d.intensity.values
def lor(x,amp,cen,wid):
    return amp*(wid/2)**2/((x-cen)**2+(wid/2)**2)
def m1(x,b0,b1,aD,cD,wD,aG,cG,wG,aDp,cDp,wDp):
    return b0+b1*(x-1500)/100+lor(x,aD,cD,wD)+lor(x,aG,cG,wG)+lor(x,aDp,cDp,wDp)
# window 1: 1150-1800 (D, G, D')
s=(x>1150)&(x<1800)
p=Parameters()
p.add_many(('b0',2600),('b1',0),('aD',800,True,0,3000),('cD',1350,True,1320,1380),('wD',30,True,5,100),
 ('aG',5000,True,0),('cG',1582,True,1570,1595),('wG',15,True,4,60),
 ('aDp',300,True,0,2000),('cDp',1615,True,1600,1630),('wDp',12,True,4,40))
r=Model(m1).fit(y[s],p,x=x[s])
print('WINDOW 1 (1150-1800)'); 
for k,v in r.params.items(): print(f'  {k:6s} {v.value:10.2f} +/- {v.stderr if v.stderr is None else round(v.stderr,2)}')
print('  chi2red', round(r.redchi,1), 'resid std', round(np.std(r.residual),1))
# window 2: 2550-2850 (2D) linear bg
def m2(x,b0,b1,a,c,w):
    return b0+b1*(x-2700)/100+lor(x,a,c,w)
s2=(x>2550)&(x<2850)
p2=Parameters()
p2.add_many(('b0',1600),('b1',0),('a',15000,True,0),('c',2699,True,2670,2730),('w',30,True,5,100))
r2=Model(m2).fit(y[s2],p2,x=x[s2])
print('WINDOW 2 (2550-2850)')
for k,v in r2.params.items(): print(f'  {k:6s} {v.value:10.2f} +/- {v.stderr if v.stderr is None else round(v.stderr,2)}')
print('  chi2red', round(r2.redchi,1), 'resid std', round(np.std(r2.residual),1))
"

